import React, { createContext, useState, useContext, useEffect } from 'react';
import axios from 'axios';

// Create Context
const AuthContext = createContext();

// API Base URL
const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

// Axios instance with interceptors
const api = axios.create({
  baseURL: API_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Add token to requests automatically
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('burbestie_token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Handle 401 errors (unauthorized)
api.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response && error.response.status === 401) {
      // Clear token and redirect to login
      localStorage.removeItem('burbestie_token');
      localStorage.removeItem('burbestie_user');
      window.location.href = '/login';
    }
    return Promise.reject(error);
  }
);

// AuthProvider Component
export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Check if user is logged in on mount
  useEffect(() => {
    checkAuth();
  }, []);

  // Check authentication status
  const checkAuth = async () => {
    try {
      const savedToken = localStorage.getItem('burbestie_token');
      const savedUser = localStorage.getItem('burbestie_user');

      if (savedToken && savedUser) {
        setToken(savedToken);
        setUser(JSON.parse(savedUser));

        // Verify token is still valid
        try {
          const response = await api.get('/api/auth/me');
          setUser(response.data.user);
        } catch (err) {
          // Token invalid, clear everything
          logout();
        }
      }
    } catch (err) {
      console.error('Auth check error:', err);
    } finally {
      setLoading(false);
    }
  };

  // Register new user
  const register = async (phone, username, password) => {
    try {
      setLoading(true);
      setError(null);

      const response = await api.post('/api/auth/register', {
        phone,
        username,
        password,
      });

      // Return temp token and OTP for verification
      return {
        success: true,
        tempToken: response.data.tempToken,
        otp: response.data.otp, // Only in development
        message: response.data.message,
      };
    } catch (err) {
      const errorMessage = err.response?.data?.message || 'Registration failed';
      setError(errorMessage);
      return {
        success: false,
        message: errorMessage,
      };
    } finally {
      setLoading(false);
    }
  };

  // Verify OTP
  const verifyOTP = async (phone, otp, tempToken) => {
    try {
      setLoading(true);
      setError(null);

      const response = await api.post('/api/auth/verify-otp', {
        phone,
        otp,
        tempToken,
      });

      const { token: newToken, user: newUser } = response.data;

      // Save to localStorage
      localStorage.setItem('burbestie_token', newToken);
      localStorage.setItem('burbestie_user', JSON.stringify(newUser));

      // Update state
      setToken(newToken);
      setUser(newUser);

      return {
        success: true,
        message: 'Phone verified successfully!',
      };
    } catch (err) {
      const errorMessage = err.response?.data?.message || 'OTP verification failed';
      setError(errorMessage);
      return {
        success: false,
        message: errorMessage,
      };
    } finally {
      setLoading(false);
    }
  };

  // Login user
  const login = async (phone, password) => {
    try {
      setLoading(true);
      setError(null);

      const response = await api.post('/api/auth/login', {
        phone,
        password,
      });

      const { token: newToken, user: newUser } = response.data;

      // Save to localStorage
      localStorage.setItem('burbestie_token', newToken);
      localStorage.setItem('burbestie_user', JSON.stringify(newUser));

      // Update state
      setToken(newToken);
      setUser(newUser);

      return {
        success: true,
        message: 'Login successful!',
      };
    } catch (err) {
      const errorMessage = err.response?.data?.message || 'Login failed';
      setError(errorMessage);
      return {
        success: false,
        message: errorMessage,
      };
    } finally {
      setLoading(false);
    }
  };

  // Logout user
  const logout = () => {
    // Clear localStorage
    localStorage.removeItem('burbestie_token');
    localStorage.removeItem('burbestie_user');

    // Clear state
    setToken(null);
    setUser(null);
    setError(null);
  };

  // Update user profile
  const updateProfile = async (updates) => {
    try {
      setLoading(true);
      setError(null);

      const response = await api.put('/api/auth/profile', updates);

      const updatedUser = response.data.user;

      // Update localStorage
      localStorage.setItem('burbestie_user', JSON.stringify(updatedUser));

      // Update state
      setUser(updatedUser);

      return {
        success: true,
        message: 'Profile updated successfully!',
        user: updatedUser,
      };
    } catch (err) {
      const errorMessage = err.response?.data?.message || 'Profile update failed';
      setError(errorMessage);
      return {
        success: false,
        message: errorMessage,
      };
    } finally {
      setLoading(false);
    }
  };

  // Get current user
  const getCurrentUser = async () => {
    try {
      const response = await api.get('/api/auth/me');
      const currentUser = response.data.user;

      // Update state and localStorage
      setUser(currentUser);
      localStorage.setItem('burbestie_user', JSON.stringify(currentUser));

      return {
        success: true,
        user: currentUser,
      };
    } catch (err) {
      const errorMessage = err.response?.data?.message || 'Failed to get user';
      return {
        success: false,
        message: errorMessage,
      };
    }
  };

  // Context value
  const value = {
    user,
    token,
    loading,
    error,
    isAuthenticated: !!token && !!user,
    register,
    verifyOTP,
    login,
    logout,
    updateProfile,
    getCurrentUser,
    api, // Export api instance for use in other components
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

// Custom hook to use auth context
export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

// Export api instance for use in services
export { api };

export default AuthContext;
